// 2D / 3D 体验馆共享的数据与类型定义。
// 3D 版（experience3d/）与 2D 版（ExperiencePage.tsx）以此为唯一信息架构事实源。

export type NodeColor = "cyan" | "violet" | "amber";

// 3D 端每个节点独占的几何形状，11 个节点两两不同，core 固定为 "brain"。
export type NodeShape =
  | "brain"
  | "octahedron"
  | "box"
  | "icosahedron"
  | "torus"
  | "dodecahedron"
  | "capsule"
  | "shield"
  | "sphere"
  | "tetrahedron"
  | "cylinder";

export type ExperienceNode = {
  id: string;
  x: number;
  y: number;
  radius: number;
  color: NodeColor;
  shape: NodeShape;
  labelKey: string;
  titleKey: string;
  bodyKey: string;
  items: string[];
};

export type SceneBurst = {
  x: number;
  y: number;
  created: number;
  color: NodeColor;
};

export type ThemeName = "dark" | "light";

export type ExperiencePalette = {
  bg: string;
  grid: string;
  line: string;
  text: string;
  muted: string;
  cyan: string;
  violet: string;
  amber: string;
  glow: string;
};

