/** 归一化坐标 [0,1]² → 3D 世界 XZ 平面坐标（48×48 世界单位） */
export const WORLD_SIZE = 48;
export function toWorld(nx: number, ny: number): [number, number] {
  return [(nx - 0.5) * WORLD_SIZE, (ny - 0.5) * WORLD_SIZE];
}

/** 节点半径（2D 像素）→ 3D 世界半径 */
export function toWorldRadius(radius: number): number {
  return (radius / 35) * 1.4;
}
